// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
// beaker wall     → CylinderGeometry(1.1,1.1,2.2,64,1,open)  MeshPhysicalMaterial #cfe3e6 op .28
