// caption         → addLabel (2 lines) at (0,-1.78,0)        #333
──────────────────────────────────────────────────────────────────────────── */

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-4, 6, 5);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(4, 2, -4);
scene.add(fillLight);

/* ── shared textures ────────────────────────────────────────────────────── */
function makeGlyphTexture(ch, color, px) {
  const S = 128;
  const cv = document.createElement('canvas'); cv.width = cv.height = S;
  const g = cv.getContext('2d');
  g.clearRect(0, 0, S, S);
  g.fillStyle = color;
  g.font = 'bold ' + (px || 104) + 'px sans-serif';
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(ch, S / 2, S * 0.54);
  const t = new THREE.CanvasTexture(cv);
  t.needsUpdate = true;
  return t;
}
function makeGlowTexture() {
  const S = 256;
  const cv = document.createElement('canvas'); cv.width = cv.height = S;
  const g = cv.getContext('2d');
  const grd = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  grd.addColorStop(0.0, 'rgba(255,240,150,1)');
  grd.addColorStop(0.25, 'rgba(255,228,90,0.65)');
  grd.addColorStop(0.55, 'rgba(255,220,70,0.22)');
  grd.addColorStop(1.0, 'rgba(255,220,70,0)');
  g.fillStyle = grd; g.fillRect(0, 0, S, S);
  const t = new THREE.CanvasTexture(cv); t.needsUpdate = true;
  return t;
}

/* ── materials ──────────────────────────────────────────────────────────── */
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xcfe3e6, transparent: true, opacity: 0.30, roughness: 0.08,
  metalness: 0.0, clearcoat: 1.0, side: THREE.DoubleSide, depthWrite: false
});
const liquidMat = new THREE.MeshPhysicalMaterial({
  color: 0xbfe7ee, transparent: true, opacity: 0.45, roughness: 0.15,
  metalness: 0.0, side: THREE.DoubleSide, depthWrite: false
});
const bandMat = new THREE.MeshPhysicalMaterial({
  color: 0xa9dde8, transparent: true, opacity: 0.6, roughness: 0.15,
  side: THREE.DoubleSide, depthWrite: false
});
const plateMat = new THREE.MeshStandardMaterial({ color: 0x9a9a9a, roughness: 0.45, metalness: 0.55 });
const stemMat = new THREE.MeshStandardMaterial({ color: 0xb4b4b4, roughness: 0.4, metalness: 0.6 });
const wireMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.6 });
const outletMat = new THREE.MeshStandardMaterial({ color: 0x8d9298, roughness: 0.6, metalness: 0.2 });
const baseMat = new THREE.MeshStandardMaterial({ color: 0x9aa0a6, roughness: 0.35, metalness: 0.75 });

/* ── beaker ─────────────────────────────────────────────────────────────── */
const beaker = new THREE.Group();
const wall = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 1.1, 2.2, 64, 1, true), glassMat);
wall.position.y = 0; wall.renderOrder = 4;
beaker.add(wall);
const bottom = new THREE.Mesh(new THREE.CircleGeometry(1.1, 64), glassMat);
bottom.rotation.x = -Math.PI / 2; bottom.position.y = -1.1; bottom.renderOrder = 3;
beaker.add(bottom);
const rim = new THREE.Mesh(new THREE.TorusGeometry(1.1, 0.055, 12, 72), glassMat);
rim.rotation.x = Math.PI / 2; rim.position.y = 1.1; rim.renderOrder = 4;
beaker.add(rim);
const rimLow = new THREE.Mesh(new THREE.TorusGeometry(1.1, 0.035, 10, 72), glassMat);
rimLow.rotation.x = Math.PI / 2; rimLow.position.y = 0.96; rimLow.renderOrder = 4;
beaker.add(rimLow);
const spoutCurve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(-1.02, 1.10, 0.30),
  new THREE.Vector3(-1.24, 1.16, 0.16),
  new THREE.Vector3(-1.32, 1.06, 0.00),
  new THREE.Vector3(-1.24, 1.16, -0.16),
  new THREE.Vector3(-1.02, 1.10, -0.30)
]);
const spout = new THREE.Mesh(new THREE.TubeGeometry(spoutCurve, 40, 0.05, 10, false), glassMat);
spout.renderOrder = 4;
beaker.add(spout);
scene.add(beaker);
registerInteractive(wall, {
  title: 'Conductivity cell',
  tooltip: 'The beaker and its solution',
  body: 'The beaker holds the solution being tested. The solution itself is part of the electrical circuit: current can only flow through it if the dissolved solute supplies mobile charged particles (ions).'
});

/* ── liquid ─────────────────────────────────────────────────────────────── */
const liquid = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.05, 1.40, 48), liquidMat);
liquid.position.y = -0.35; liquid.renderOrder = 2;
scene.add(liquid);
const band = new THREE.Mesh(new THREE.CylinderGeometry(1.052, 1.052, 0.07, 48), bandMat);
band.position.y = 0.34; band.renderOrder = 3;
scene.add(band);
const surface = new THREE.Mesh(new THREE.CircleGeometry(1.05, 48), bandMat);
surface.rotation.x = -Math.PI / 2; surface.position.y = 0.35; surface.renderOrder = 3;
scene.add(surface);

/* ── electrodes ─────────────────────────────────────────────────────────── */
const PLATE_TILT = THREE.MathUtils.degToRad(-16);
function makePlate(x, glyphChar, glyphColor) {
  const g = new THREE.Group();
  g.position.set(x, -0.10, 0);
  g.rotation.y = PLATE_TILT;
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.04, 1.5, 0.9), plateMat);
  g.add(body);
  const edge = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.04, 0.9),
    new THREE.MeshStandardMaterial({ color: 0xc8c8c8, roughness: 0.3, metalness: 0.6 }));
