    } else {
      if (running) {
        p.obj.position.x += p.dir * p.speed * dt;
        if (p.dir < 0 && p.obj.position.x < -0.40) {
          p.obj.position.set(0.40, BYmin + Math.random() * (BYmax - BYmin), (Math.random() * 2 - 1) * BZ);
