/* ── light bulb ─────────────────────────────────────────────────────────── */
const bulbGlassMat = new THREE.MeshPhysicalMaterial({
  color: 0xf2f7f9, transparent: true, opacity: 0.38, roughness: 0.05,
  metalness: 0.0, clearcoat: 1.0, emissive: new THREE.Color(0xffe14d),
  emissiveIntensity: 0.0, side: THREE.DoubleSide, depthWrite: false
});
const envelope = new THREE.Mesh(new THREE.SphereGeometry(0.45, 40, 30), bulbGlassMat);
envelope.position.set(2.2, 3.52, 0); envelope.renderOrder = 5;
scene.add(envelope);
const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.30, 0.28, 28, 1, true), bulbGlassMat);
neck.position.set(2.2, 3.16, 0); neck.renderOrder = 5;
scene.add(neck);
const screw = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.19, 0.40, 28), baseMat);
screw.position.set(2.2, 2.96, 0);
