for (let i = 0; i < 3; i++) {
  const rib = new THREE.Mesh(new THREE.TorusGeometry(0.183, 0.022, 8, 28), baseMat);
  rib.rotation.x = Math.PI / 2;
  rib.position.set(2.2, 3.06 - i * 0.11, 0);
