}
const tip = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 10),
  new THREE.MeshStandardMaterial({ color: 0x3a3a3a, roughness: 0.6 }));
tip.position.set(2.2, 2.74, 0);
scene.add(tip);
const postMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.4, metalness: 0.7 });
[-0.075, 0.075].forEach(dx => {
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.34, 8), postMat);
  post.position.set(2.2 + dx, 3.38, 0);
  scene.add(post);
