  if (type === 'kcl') {
    const n = Math.max(2, Math.round(6 * s));
    const cat = Math.ceil(n / 2);
    return { pairs: 0, cat: cat, an: n - cat };
  }
  return {
    pairs: Math.max(1, Math.round(3 * s)),
    cat: Math.max(1, Math.round(1 * s)),
    an: Math.max(1, Math.round(1 * s))
  };
}

