    if (p.kind === 'neutral') {
      if (running) {
        p.obj.position.addScaledVector(p.vel, dt);
        p.obj.rotation.x += p.spin.x * dt;
        p.obj.rotation.y += p.spin.y * dt;
        p.obj.rotation.z += p.spin.z * dt;
        const q = p.obj.position;
        if (q.x < -BX || q.x > BX) { p.vel.x *= -1; q.x = THREE.MathUtils.clamp(q.x, -BX, BX); }
        if (q.y < BYmin || q.y > BYmax) { p.vel.y *= -1; q.y = THREE.MathUtils.clamp(q.y, BYmin, BYmax); }
        if (q.z < -BZ || q.z > BZ) { p.vel.z *= -1; q.z = THREE.MathUtils.clamp(q.z, -BZ, BZ); }
      }
    } else {
      if (running) {
        p.obj.position.x += p.dir * p.speed * dt;
        if (p.dir < 0 && p.obj.position.x < -TRAVEL) {
          p.obj.position.set(TRAVEL, BYmin + Math.random() * (BYmax - BYmin), (Math.random() * 2 - 1) * BZ);
        } else if (p.dir > 0 && p.obj.position.x > TRAVEL) {
          p.obj.position.set(-TRAVEL, BYmin + Math.random() * (BYmax - BYmin), (Math.random() * 2 - 1) * BZ);
        }
      }
      _dirToCam.copy(camera.position).sub(p.obj.position).normalize().multiplyScalar(0.104);
      p.glyph.position.copy(_dirToCam);
    }
  }
}

