  const b = brightness;
  filamentMat.emissiveIntensity = 0.05 + 3.2 * b;
  filamentMat.color.setHex(b > 0.02 ? 0xffc87a : 0x6b6b6b);
  bulbGlassMat.emissiveIntensity = 0.75 * b;
  glowSprite.material.opacity = Math.min(1, 1.05 * b);
  const s = 0.9 + 1.5 * b;
  glowSprite.scale.set(s, s, 1);
  bulbLight.intensity = 3.0 * b;
}

function updateFade(dt) {
  if (fadeDir === -1) {
    fadeV -= dt * 5;
    if (fadeV <= 0) {
      fadeV = 0;
      if (pendingType) solution = pendingType;
      pendingType = null;
      caption.div.innerHTML = CAPTIONS[solution];
      refreshParticles(true);
      fadeDir = 1;
    }
  } else if (fadeDir === 1) {
    fadeV += dt * 4;
    if (fadeV >= 1) { fadeV = 1; fadeDir = 0; }
  } else {
    return;
  }
  for (const m of fadeMats) m.opacity = fadeV;
}

function updateTween(dt) {
  if (!concTween) return;
  concTween.t += dt;
  const k = Math.min(1, concTween.t / concTween.dur);
  const e = k * k * (3 - 2 * k);
  const v = concTween.from + (concTween.to - concTween.from) * e;
  setConcentration(Math.round(v * 20) / 20);
  if (k >= 1) concTween = null;
}

function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, _clock.getDelta());
  updateTween(dt);
  updateFade(dt);
  updateParticles(dt);
  updateBulb(dt);
}
