/* ── shared textures ────────────────────────────────────────────────────── */
function makeGlyphTexture(ch, color, px) {
  const S = 128;
  const cv = document.createElement('canvas'); cv.width = cv.height = S;
  const g = cv.getContext('2d');
  g.clearRect(0, 0, S, S);
  g.fillStyle = color;
  g.font = 'bold ' + (px || 104) + 'px sans-serif';
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(ch, S / 2, S * 0.54);
  const t = new THREE.CanvasTexture(cv);
  t.needsUpdate = true;
  return t;
}
function makeGlowTexture() {
  const S = 256;
  const cv = document.createElement('canvas'); cv.width = cv.height = S;
  const g = cv.getContext('2d');
  const grd = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  grd.addColorStop(0.0, 'rgba(255,240,150,1)');
  grd.addColorStop(0.25, 'rgba(255,228,90,0.65)');
  grd.addColorStop(0.55, 'rgba(255,220,70,0.22)');
  grd.addColorStop(1.0, 'rgba(255,220,70,0)');
  g.fillStyle = grd; g.fillRect(0, 0, S, S);
  const t = new THREE.CanvasTexture(cv); t.needsUpdate = true;
  return t;
}

