  const glyphMatF = new THREE.MeshBasicMaterial({ map: tex, transparent: true });
  const glyphF = new THREE.Mesh(new THREE.PlaneGeometry(0.30, 0.30), glyphMatF);
  glyphF.position.set(0.026, 0.45, 0.06);
  glyphF.rotation.y = Math.PI / 2;
