  const glyphB = new THREE.Mesh(new THREE.PlaneGeometry(0.30, 0.30), glyphMatF);
  glyphB.position.set(-0.026, 0.45, 0.06);
  glyphB.rotation.y = -Math.PI / 2;
  g.add(glyphB);
  scene.add(g);
  return { group: g, body: body };
}
