/* ── particle resources (shared) ────────────────────────────────────────── */
const sphereGeo = new THREE.SphereGeometry(0.10, 20, 14);
const greenMat = new THREE.MeshStandardMaterial({
  color: 0x7ac143, roughness: 0.35, metalness: 0.05,
  emissive: new THREE.Color(0x2f5c18), emissiveIntensity: 0.25,
  transparent: true, opacity: 1
});
const arrowMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.6, transparent: true, opacity: 1 });
const shaftGeo = new THREE.CylinderGeometry(0.012, 0.012, 0.34, 8);
const headGeo = new THREE.ConeGeometry(0.038, 0.11, 12);
const plusMat = new THREE.SpriteMaterial({ map: makeGlyphTexture('+', '#111111', 120), transparent: true, opacity: 1 });
const minusMat = new THREE.SpriteMaterial({ map: makeGlyphTexture('\u2212', '#111111', 120), transparent: true, opacity: 1 });
const fadeMats = [greenMat, arrowMat, plusMat, minusMat];

const particleGroup = new THREE.Group();
scene.add(particleGroup);
let particles = [];

const BX = 0.46, BYmin = -0.88, BYmax = 0.16, BZ = 0.45;
const TRAVEL = PLATE_X - 0.12;

function makeArrow(dir) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(shaftGeo, arrowMat);
  shaft.rotation.z = Math.PI / 2;
  shaft.position.x = dir * 0.32;
  g.add(shaft);
  const head = new THREE.Mesh(headGeo, arrowMat);
  head.rotation.z = dir > 0 ? -Math.PI / 2 : Math.PI / 2;
  head.position.x = dir * 0.54;
  g.add(head);
  return g;
}

function addIon(sign) {
  const m = new THREE.Mesh(sphereGeo, greenMat);
  m.position.set(
    (Math.random() * 2 - 1) * BX,
    BYmin + Math.random() * (BYmax - BYmin),
    (Math.random() * 2 - 1) * BZ
  );
  const glyph = new THREE.Sprite(sign > 0 ? plusMat : minusMat);
  glyph.scale.set(0.15, 0.15, 1);
  m.add(glyph);
  const dir = sign > 0 ? -1 : 1;          // cations -> left (-) plate, anions -> right (+)
  const arrow = makeArrow(dir);
  arrow.position.x = dir * 0.06;
  m.add(arrow);
  particleGroup.add(m);
  particles.push({ obj: m, kind: 'ion', dir: dir, glyph: glyph, speed: 0.20 + Math.random() * 0.10 });
}

function addPair() {
  const g = new THREE.Group();
  const a = new THREE.Mesh(sphereGeo, greenMat); a.position.set(-0.08, 0, 0);
  const b = new THREE.Mesh(sphereGeo, greenMat); b.position.set(0.08, 0, 0);
  g.add(a); g.add(b);
  g.position.set(
    (Math.random() * 2 - 1) * BX,
    BYmin + Math.random() * (BYmax - BYmin),
    (Math.random() * 2 - 1) * BZ
  );
  g.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
  particleGroup.add(g);
  particles.push({
    obj: g, kind: 'neutral',
    vel: new THREE.Vector3((Math.random() - 0.5) * 0.09, (Math.random() - 0.5) * 0.06, (Math.random() - 0.5) * 0.09),
    spin: new THREE.Vector3((Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8)
  });
}

function clearParticles() {
  for (const p of particles) particleGroup.remove(p.obj);
  particles = [];
}

function computeCounts(type, c) {
  if (c <= 0.001) return { pairs: 0, cat: 0, an: 0 };
  const s = 2 * c;
  if (type === 'ethanol') return { pairs: Math.max(1, Math.round(5 * s)), cat: 0, an: 0 };
  if (type === 'kcl') {
    const n = Math.max(2, Math.round(6 * s));
    const cat = Math.ceil(n / 2);
    return { pairs: 0, cat: cat, an: n - cat };
  }
  return {
    pairs: Math.max(1, Math.round(3 * s)),
    cat: Math.max(1, Math.round(1 * s)),
    an: Math.max(1, Math.round(1 * s))
  };
}

function buildParticles(counts) {
  clearParticles();
  for (let i = 0; i < counts.pairs; i++) addPair();
  for (let i = 0; i < counts.cat; i++) addIon(+1);
  for (let i = 0; i < counts.an; i++) addIon(-1);
}

