const fadeMats = [greenMat, arrowMat, plusMat, minusMat];

const particleGroup = new THREE.Group();
scene.add(particleGroup);
let particles = [];

// Volume the particles live in: between the two plates, inside the liquid.
const BX = 0.30, BYmin = -0.80, BYmax = 0.14, BZ = 0.44;
const TRAVEL = PLATE_X - 0.10;

/* Jittered-grid slots: stratified spawn positions so particles never clump. */
let slots = [];
function buildSlots(n) {
  slots = [];
  const ny = Math.max(1, Math.min(4, n));
  const nz = Math.max(1, Math.ceil(n / ny));
  for (let iy = 0; iy < ny; iy++) {
    for (let iz = 0; iz < nz; iz++) {
      const fy = (iy + 0.5) / ny, fz = (iz + 0.5) / nz;
      slots.push(new THREE.Vector3(
        (Math.random() * 2 - 1) * BX * 0.85,
        BYmin + fy * (BYmax - BYmin) + (Math.random() - 0.5) * (BYmax - BYmin) / (ny * 2.6),
        -BZ + fz * 2 * BZ + (Math.random() - 0.5) * (2 * BZ) / (nz * 2.6)
      ));
    }
  }
  // shuffle
  for (let i = slots.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = slots[i]; slots[i] = slots[j]; slots[j] = t;
  }
}
function nextSlot() {
  if (!slots.length) buildSlots(4);
  return slots.pop();
}
/* Respawn far from every other particle of the same kind. */
function spreadRespawn(ion) {
  let best = null, bestD = -1;
  for (let k = 0; k < 14; k++) {
    const y = BYmin + Math.random() * (BYmax - BYmin);
    const z = (Math.random() * 2 - 1) * BZ;
    let dmin = Infinity;
    for (const p of particles) {
      if (p === ion) continue;
      const q = p.obj.position;
      const dy = q.y - y, dz = q.z - z;
      dmin = Math.min(dmin, Math.sqrt(dy * dy + dz * dz));
    }
    if (dmin > 0.34) { best = [y, z]; break; }
    if (dmin > bestD) { bestD = dmin; best = [y, z]; }
  }
  return best;
}

function makeArrow(dir) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(shaftGeo, arrowMat);
  shaft.rotation.z = Math.PI / 2;
  shaft.position.x = dir * 0.30;
  g.add(shaft);
  const head = new THREE.Mesh(headGeo, arrowMat);
  head.rotation.z = dir > 0 ? -Math.PI / 2 : Math.PI / 2;
  head.position.x = dir * 0.50;
  g.add(head);
  return g;
}

function addIon(sign) {
  const m = new THREE.Mesh(sphereGeo, greenMat);
  m.position.copy(nextSlot());
  const glyph = new THREE.Sprite(sign > 0 ? plusMat : minusMat);
  glyph.scale.set(0.17, 0.17, 1);
  m.add(glyph);
  const dir = sign > 0 ? -1 : 1;          // cations -> left (-) plate, anions -> right (+)
  const arrow = makeArrow(dir);
  arrow.position.x = dir * 0.05;
  m.add(arrow);
  particleGroup.add(m);
  particles.push({ obj: m, kind: 'ion', dir: dir, glyph: glyph, speed: 0.19 + Math.random() * 0.09 });
}

function addPair() {
  const g = new THREE.Group();
  const a = new THREE.Mesh(sphereGeo, greenMat); a.position.set(-0.08, 0, 0);
  const b = new THREE.Mesh(sphereGeo, greenMat); b.position.set(0.08, 0, 0);
  g.add(a); g.add(b);
  g.position.copy(nextSlot());
  g.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
  particleGroup.add(g);
  particles.push({
    obj: g, kind: 'neutral',
    vel: new THREE.Vector3((Math.random() - 0.5) * 0.08, (Math.random() - 0.5) * 0.05, (Math.random() - 0.5) * 0.08),
    spin: new THREE.Vector3((Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8, (Math.random() - 0.5) * 0.8)
  });
}

function clearParticles() {
  for (const p of particles) particleGroup.remove(p.obj);
  particles = [];
}

function computeCounts(type, c) {
  if (c <= 0.001) return { pairs: 0, cat: 0, an: 0 };
  const s = 2 * c;
  if (type === 'ethanol') return { pairs: Math.max(1, Math.round(5 * s)), cat: 0, an: 0 };
  if (type === 'kcl') {
    const n = Math.max(2, Math.round(6 * s));
    const cat = Math.ceil(n / 2);
    return { pairs: 0, cat: cat, an: n - cat };
  }
  return {
    pairs: Math.max(1, Math.round(3 * s)),
    cat: Math.max(1, Math.round(1 * s)),
    an: Math.max(1, Math.round(1 * s))
  };
}

function buildParticles(counts) {
  clearParticles();
  const total = counts.pairs + counts.cat + counts.an;
  buildSlots(Math.max(total, 1));
  for (let i = 0; i < counts.pairs; i++) addPair();
  for (let i = 0; i < counts.cat; i++) addIon(+1);
  for (let i = 0; i < counts.an; i++) addIon(-1);
}

/* ── state ──────────────────────────────────────────────────────────────── */
const CAPTIONS = {
  ethanol: 'ethanol<br>No conductivity',
  kcl: 'KCl<br>High conductivity',
  acetic: 'acetic acid solution<br>Low conductivity'
};
let solution = 'ethanol';
let concentration = 0.5;
let running = true;
let lastCounts = { pairs: -1, cat: -1, an: -1 };
let brightness = 0, brightnessTarget = 0;
let fadeV = 1, fadeDir = 0, pendingType = null;

/* ── labels ─────────────────────────────────────────────────────────────── */
const caption = addLabel(CAPTIONS.ethanol, new THREE.Vector3(0, -1.80, 0),
  { fontSize: '20px', color: '#1c1c1c' });
caption.div.style.textAlign = 'center';
caption.div.style.lineHeight = '1.3';
caption.div.style.fontWeight = '500';

addLabel('\u2212 electrode', new THREE.Vector3(-PLATE_X, 0.92, 0.45),
  { fontSize: '14px', color: '#111', bold: true, offset: [-44, -10], background: 'rgba(255,255,255,0.85)' });
addLabel('+ electrode', new THREE.Vector3(PLATE_X, 0.92, 0.45),
  { fontSize: '14px', color: '#c02c2c', bold: true, offset: [46, -10], background: 'rgba(255,255,255,0.85)' });
addLabel('wall outlet', new THREE.Vector3(-3.35, 2.05, 0),
  { fontSize: '13px', color: '#333', offset: [0, 14] });
const bulbLabel = addLabel('bulb: dark', new THREE.Vector3(2.2, 2.62, 0),
  { fontSize: '15px', color: '#222', bold: true, offset: [0, 26], background: 'rgba(255,255,255,0.85)' });

function targetBrightness() {
  if (solution === 'ethanol') return 0;
  if (solution === 'kcl') return concentration;
  return 0.25 * concentration;
}

function bulbWord(b) {
  if (b < 0.03) return 'dark';
  if (b < 0.35) return 'dim';
  if (b < 0.7) return 'glowing';
  return 'bright';
}

function updateReadout() {
  const ions = lastCounts.cat + lastCounts.an;
  document.getElementById('roIons').textContent = String(ions);
  document.getElementById('roMol').textContent = String(lastCounts.pairs);
  const pct = Math.round(brightnessTarget * 100);
  document.getElementById('roBulb').textContent = bulbWord(brightnessTarget) + ' (' + pct + '%)';
  bulbLabel.div.innerHTML = 'bulb: ' + bulbWord(brightnessTarget);
}

function refreshParticles(force) {
  const c = computeCounts(solution, concentration);
  if (force || c.pairs !== lastCounts.pairs || c.cat !== lastCounts.cat || c.an !== lastCounts.an) {
    buildParticles(c);
    lastCounts = c;
  }
  brightnessTarget = targetBrightness();
  updateReadout();
}

function setSolution(t) {
  if (t === solution && pendingType === null) return;
  if (t === pendingType) return;
  pendingType = t;
  fadeDir = -1;
  document.getElementById('btnEth').classList.toggle('active', t === 'ethanol');
  document.getElementById('btnKcl').classList.toggle('active', t === 'kcl');
  document.getElementById('btnAcid').classList.toggle('active', t === 'acetic');
}

function setConcentration(v) {
  concentration = v;
  document.getElementById('conc').value = String(v);
  document.getElementById('concVal').textContent = v.toFixed(2);
  refreshParticles(false);
}

refreshParticles(true);

/* ── UI wiring ──────────────────────────────────────────────────────────── */
document.getElementById('btnEth').addEventListener('click', () => setSolution('ethanol'));
document.getElementById('btnKcl').addEventListener('click', () => setSolution('kcl'));
document.getElementById('btnAcid').addEventListener('click', () => setSolution('acetic'));
document.getElementById('conc').addEventListener('input', e => setConcentration(parseFloat(e.target.value)));
const btnRun = document.getElementById('btnRun');
btnRun.addEventListener('click', () => {
  running = !running;
  btnRun.textContent = running ? '\u23f8 Pause ion migration' : '\u25b6 Run the circuit (ion migration)';
  btnRun.classList.toggle('active', running);
});
const btnResetView = document.getElementById('btnReset');
btnResetView.style.display = '';
btnResetView.textContent = '\u21ba Reset view';

/* ── demo steps ─────────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'Ethanol \u2014 no conductivity',
    narration: 'Ethanol dissolves as whole neutral molecules. They drift randomly, no charge crosses the gap, and the bulb stays completely dark.',
    type: 'ethanol', conc: 0.5
  },
  {
    title: 'More ethanol still won\u2019t light it',
    narration: 'Pushing the concentration to maximum crowds the beaker with molecules but adds zero ions \u2014 the bulb remains off, proving conductivity depends on charge carriers, not solute amount.',
    type: 'ethanol', conc: 1
  },
  {
    title: 'KCl \u2014 high conductivity',
    narration: 'KCl dissociates completely: K\u207a ions stream toward the \u2212 plate and Cl\u207b ions toward the + plate. The dense two-way traffic of charge lights the bulb brightly.',
    type: 'kcl', conc: 0.5
  },
  {
    title: 'Dilute the strong electrolyte',
    narration: 'Lowering the concentration removes ions in proportion; the migration thins out and the bulb dims smoothly, showing brightness tracks ion density.',
    type: 'kcl', conc: 0.15
  },
  {
    title: 'Acetic acid \u2014 low conductivity',
    narration: 'At the same concentration as KCl, acetic acid only partially dissociates: a few ions migrate among many intact CH\u2083COOH molecules, so the bulb glows only dimly.',
    type: 'acetic', conc: 0.5
  }
];
let stepIdx = 0;
let concTween = null;

function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setSolution(s.type);
  concTween = { from: concentration, to: s.conc, t: 0, dur: 0.7 };
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.narration;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── camera (after geometry) ────────────────────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 80,        // near front-on reading of the printed figure, slight 3D turn
  elevationDeg: 15,
  rollDeg: 0,
  target: [-0.15, 0.85, 0],
  heightFraction: 0.80
});
const az0 = controls.getAzimuthalAngle();
controls.minAzimuthAngle = az0 - THREE.MathUtils.degToRad(40);
controls.maxAzimuthAngle = az0 + THREE.MathUtils.degToRad(40);
controls.minPolarAngle = THREE.MathUtils.degToRad(45);
controls.maxPolarAngle = THREE.MathUtils.degToRad(92);

/* ── update loop ────────────────────────────────────────────────────────── */
const _clock = new THREE.Clock();
const _dirToCam = new THREE.Vector3();

function updateParticles(dt) {
  for (const p of particles) {
    if (p.kind === 'neutral') {
      if (running) {
        p.obj.position.addScaledVector(p.vel, dt);
        p.obj.rotation.x += p.spin.x * dt;
        p.obj.rotation.y += p.spin.y * dt;
        p.obj.rotation.z += p.spin.z * dt;
        const q = p.obj.position;
        if (q.x < -BX || q.x > BX) { p.vel.x *= -1; q.x = THREE.MathUtils.clamp(q.x, -BX, BX); }
        if (q.y < BYmin || q.y > BYmax) { p.vel.y *= -1; q.y = THREE.MathUtils.clamp(q.y, BYmin, BYmax); }
        if (q.z < -BZ || q.z > BZ) { p.vel.z *= -1; q.z = THREE.MathUtils.clamp(q.z, -BZ, BZ); }
      }
    } else {
      if (running) {
        p.obj.position.x += p.dir * p.speed * dt;
        if ((p.dir < 0 && p.obj.position.x < -TRAVEL) || (p.dir > 0 && p.obj.position.x > TRAVEL)) {
          const yz = spreadRespawn(p);
          p.obj.position.set(-p.dir * TRAVEL, yz[0], yz[1]);
        }
      }
      _dirToCam.copy(camera.position).sub(p.obj.position).normalize().multiplyScalar(0.105);
      p.glyph.position.copy(_dirToCam);
    }
  }
  // gentle mutual separation so nothing reads as a clump
  for (let i = 0; i < particles.length; i++) {
    for (let j = i + 1; j < particles.length; j++) {
      const a = particles[i].obj.position, b = particles[j].obj.position;
      const dx = b.x - a.x, dy = b.y - a.y, dz = b.z - a.z;
      const d2 = dx * dx + dy * dy + dz * dz;
      const min = 0.30;
      if (d2 > 1e-6 && d2 < min * min) {
        const dist = Math.sqrt(d2);
        const push = (min - dist) * 0.5 / dist;
        a.x -= dx * push; a.y -= dy * push; a.z -= dz * push;
        b.x += dx * push; b.y += dy * push; b.z += dz * push;
        a.y = THREE.MathUtils.clamp(a.y, BYmin, BYmax);
        b.y = THREE.MathUtils.clamp(b.y, BYmin, BYmax);
        a.z = THREE.MathUtils.clamp(a.z, -BZ, BZ);
        b.z = THREE.MathUtils.clamp(b.z, -BZ, BZ);
      }
    }
  }
}

function updateBulb(dt) {
  brightness += (brightnessTarget - brightness) * Math.min(1, dt * 4.5);
  const b = brightness;
  filamentMat.emissiveIntensity = 0.05 + 3.2 * b;
  filamentMat.color.setHex(b > 0.02 ? 0xffc87a : 0x6b6b6b);
  bulbGlassMat.emissiveIntensity = 0.85 * b;
  glowSprite.material.opacity = Math.min(1, 1.1 * b);
  const s = 0.9 + 1.6 * b;
  glowSprite.scale.set(s, s, 1);
  bulbLight.intensity = 3.0 * b;
}

function updateFade(dt) {
  if (fadeDir === -1) {
    fadeV -= dt * 5;
    if (fadeV <= 0) {
      fadeV = 0;
      if (pendingType) solution = pendingType;
      pendingType = null;
      caption.div.innerHTML = CAPTIONS[solution];
      refreshParticles(true);
      fadeDir = 1;
    }
  } else if (fadeDir === 1) {
    fadeV += dt * 4;
    if (fadeV >= 1) { fadeV = 1; fadeDir = 0; }
  } else {
    return;
  }
  for (const m of fadeMats) m.opacity = fadeV;
}

function updateTween(dt) {
  if (!concTween) return;
  concTween.t += dt;
  const k = Math.min(1, concTween.t / concTween.dur);
  const e = k * k * (3 - 2 * k);
  const v = concTween.from + (concTween.to - concTween.from) * e;
  setConcentration(Math.round(v * 20) / 20);
  if (k >= 1) concTween = null;
}

function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, _clock.getDelta());
  updateTween(dt);
  updateFade(dt);
  updateParticles(dt);
  updateBulb(dt);
}
tick();
